#ifndef INCLUDE_ZEPHYR_SYS_LINEAR_RANGE_H_
#define INCLUDE_ZEPHYR_SYS_LINEAR_RANGE_H_

#include <errno.h>
#include <stdint.h>
#include <stdlib.h>

#include <zephyr/sys/util.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @defgroup linear_range Linear Range
 * @ingroup utilities
 *
 * The linear range utility implements a similar concept to the Linux kernel's
 * linear_range. It allows mapping values in a linear range (defined by a base
 * value, step, and index bounds) to and from indices.
 *
 * @{
 */

/** @brief Linear range. */
struct linear_range {
	/** Minimum value. */
	int32_t min;
	/** Step value. */
	uint32_t step;
	/** Minimum index (must be <= to maximum index). */
	uint16_t min_idx;
	/** Maximum index (must be >= to minimum index). */
	uint16_t max_idx;
};

/**
 * @brief Initializer for @ref linear_range.
 *
 * @param _min Minimum value in range.
 * @param _step Step value.
 * @param _min_idx Minimum index.
 * @param _max_idx Maximum index.
 */
#define LINEAR_RANGE_INIT(_min, _step, _min_idx, _max_idx)			\
	{									\
		.min = (_min),							\
		.step = (_step),						\
		.min_idx = (_min_idx),						\
		.max_idx = (_max_idx),						\
	}

/**
 * @brief Obtain the number of values in a linear range.
 *
 * @param r Linear range instance.
 *
 * @return Number of values in @p r.
 */
static inline uint32_t linear_range_values_count(const struct linear_range *r)
{
	if (r->min_idx > r->max_idx) {
		return 0U;
	}

	return r->max_idx - r->min_idx + 1U;
}

/**
 * @brief Obtain the number of values in a group of linear ranges.
 *
 * @param r Linear range instances.
 * @param r_cnt Number of linear ranges.
 *
 * @return Number of values in @p r.
 */
static inline uint32_t linear_range_group_values_count(
	const struct linear_range *r, size_t r_cnt)
{
	uint32_t values = 0U;

	for (size_t i = 0U; i < r_cnt; i++) {
		values += linear_range_values_count(&r[i]);
	}

	return values;
}

/**
 * @brief Obtain the maximum value in a linear range.
 *
 * @param r Linear range instance.
 *
 * @return Maximum value in @p r.
 */
static inline int32_t linear_range_get_max_value(const struct linear_range *r)
{
	return r->min + (int32_t)(r->step * (r->max_idx - r->min_idx));
}

/**
 * @brief Obtain the value for a given linear range index.
 *
 * @param[in] r Linear range instance.
 * @param[in] idx Index.
 * @param[out] val Where value will be stored.
 *
 * @retval 0 If index is valid.
 * @retval -EINVAL If index is out of range.
 */
static inline int linear_range_get_value(const struct linear_range *r,
					 uint16_t idx, int32_t *val)
{
	if ((idx < r->min_idx) || (idx > r->max_idx)) {
		return -EINVAL;
	}

	*val = r->min + (int32_t)(r->step * (idx - r->min_idx));

	return 0;
}

/**
 * @brief Obtain the value for a given linear range group index.
 *
 * @param[in] r Linear range instances.
 * @param[in] r_cnt Number of linear ranges.
 * @param[in] idx Index.
 * @param[out] val Where value will be stored.
 *
 * @retval 0 If index is valid.
 * @retval -EINVAL If index is out of any range.
 */
static inline int linear_range_group_get_value(const struct linear_range *r,
					       size_t r_cnt, uint16_t idx,
					       int32_t *val)
{
	int ret = -EINVAL;

	for (size_t i = 0U; i < r_cnt; i++) {
		ret = linear_range_get_value(&r[i], idx, val);
		if (ret == 0) {
			break;
		}
	}

	return ret;
}

/**
 * @brief Obtain the index for a given linear range value.
 *
 * If the value falls out of the range, the minimum or maximum index will still
 * be stored depending on the side it falls into. If step is zero, the minimum
 * index will be stored. If the value does not fall strictly in a range step,
 * it is rounded up to the next step.
 *
 * @param[in] r Linear range instance.
 * @param[in] val Value.
 * @param[out] idx Where index will be stored.
 *
 * @retval 0 If value falls within the range.
 * @retval -EINVAL If value is not supported because of invalid range
 *                 parameters (min_idx > max_idx).
 * @retval -ERANGE If value falls out of the range.
 */
static inline int linear_range_get_index(const struct linear_range *r,
					 int32_t val, uint16_t *idx)
{
	if (r->min_idx > r->max_idx) {
		return -EINVAL;
	}

	if (val < r->min) {
		*idx = r->min_idx;
		return -ERANGE;
	}

	if (val > linear_range_get_max_value(r)) {
		*idx = r->max_idx;
		return -ERANGE;
	}

	if (r->step == 0U) {
		*idx = r->min_idx;
		return 0;
	}

	*idx = r->min_idx + DIV_ROUND_UP((uint32_t)(val - r->min), r->step);

	return 0;
}

/**
 * @brief Obtain the index for a given linear range group value.
 *
 * The first matching range will be used. Read @ref linear_range_get_index for
 *More details on how index is resolved.
 *
 * @param[in] r Linear range instances.
 * @param[in] r_cnt Number of linear ranges.
 * @param[in] val Value.
 * @param[out] idx Where index will be stored.
 *
 * @retval 0 If value falls within the range.
 * @retval -EINVAL If value is not supported by any range.
 * @retval -ERANGE If value falls out of the range.
 */
static inline int linear_range_group_get_index(const struct linear_range *r,
					       size_t r_cnt, int32_t val,
					       uint16_t *idx)
{
	for (size_t i = 0U; i < r_cnt; i++) {
		if (val > linear_range_get_max_value(&r[i]) &&
		    (i < (r_cnt - 1U))) {
			continue;
		}

		return linear_range_get_index(&r[i], val, idx);
	}

	return -EINVAL;
}

/**
 * @brief Obtain the index for a given window in a linear range.
 *
 * If the window is wider than a single step, the index corresponding to the
 * lowest value within the window is stored.
 *
 * @param[in] r Linear range instance.
 * @param[in] val_min Minimum window value.
 * @param[in] val_max Maximum window value.
 * @param[out] idx Where index will be stored.
 *
 * @retval 0 If window is valid and intersects with range.
 * @retval -EINVAL If window lies completely out of the range or range
 *                 parameters are invalid.
 * @retval -ERANGE If window is partially out of the range.
 */
static inline int linear_range_get_win_index(const struct linear_range *r,
					     int32_t val_min, int32_t val_max,
					     uint16_t *idx)
{
	int32_t r_max;

	if ((r->min_idx > r->max_idx) || (val_min > val_max)) {
		return -EINVAL;
	}

	r_max = linear_range_get_max_value(r);
	if ((val_max < r->min) || (val_min > r_max)) {
		return -EINVAL;
	}

	if (r->step == 0U) {
		*idx = r->min_idx;
		if ((val_min < r->min) || (val_max > r_max)) {
			return -ERANGE;
		}
		return 0;
	}

	if (val_min < r->min) {
		*idx = r->min_idx;
		return -ERANGE;
	}

	*idx = r->min_idx + DIV_ROUND_UP((uint32_t)(val_min - r->min), r->step);
	if ((r->min + (int32_t)(r->step * (*idx - r->min_idx))) > val_max) {
		return -EINVAL;
	}

	if (val_max > r_max) {
		return -ERANGE;
	}

	return 0;
}

/**
 * @brief Obtain the index for a given window in a linear range group.
 *
 * @param[in] r Linear range instances.
 * @param[in] r_cnt Number of linear ranges.
 * @param[in] val_min Minimum window value.
 * @param[in] val_max Maximum window value.
 * @param[out] idx Where index will be stored.
 *
 * @retval 0 If window is valid and intersects with range.
 * @retval -EINVAL If window lies completely out of the range or range
 *                 parameters are invalid.
 */
static inline int linear_range_group_get_win_index(
	const struct linear_range *r, size_t r_cnt, int32_t val_min,
	int32_t val_max, uint16_t *idx)
{
	for (size_t i = 0U; i < r_cnt; i++) {
		int ret;

		ret = linear_range_get_win_index(&r[i], val_min, val_max, idx);
		if (ret != -EINVAL) {
			return ret;
		}
	}

	return -EINVAL;
}

/** @} */

#ifdef __cplusplus
}
#endif

#endif /* INCLUDE_ZEPHYR_SYS_LINEAR_RANGE_H_ */
